// ── Auswahl und Aufbau ─────────────────────────────────────────────────────
const DATA = { bia: BIA, plan: PLAN, exercise: EXERCISE }
// Sprachen mit Inhalt; alles andere fällt auf Englisch zurück
const LANGUAGES = reg.withData(PURPOSE_INTRO)
const pickLang = l => (LANGUAGES.includes(l) ? l : 'en')
const split = s => String(s).split(',').map(x => x.trim()).filter(Boolean)
const bullets = (items, l) => items.map(i => `- ${i[l]}`).join('\n')

// Liste der Vorlagen einer Art → [{ id, title }]
function list(kind, lang) {
  if (!KINDS.includes(kind)) return null
  const l = pickLang(lang)
  return Object.entries(DATA[kind]).map(([id, t]) => ({ id, title: t.title[l] }))
}

function planText(t, l) {
  return [
    `# ${t.title[l]}`, '',
    `## ${H.purpose[l]}`, PURPOSE_INTRO[l], '', t.scope[l], '',
    `## ${H.activation[l]}`, bullets(t.activation, l), '',
    `## ${H.roles[l]}`, bullets(ROLES, l), '',
    `## ${H.immediate[l]}`, bullets(t.immediate, l), '',
    `## ${H.recovery[l]}`, bullets(t.recovery, l), '',
    `## ${H.comms[l]}`, bullets(t.comms, l), '',
    `## ${H.normal[l]}`, bullets(NORMAL, l), '',
    `## ${H.upkeep[l]}`, bullets(UPKEEP, l), '',
  ].join('\n')
}

function exerciseText(t, l) {
  return [
    `## ${H.scenario[l]}`, t.scenario[l], '',
    `## ${H.objectives[l]}`, bullets(t.objectives, l), '',
    `## ${H.injects[l]}`, bullets(t.injects, l), '',
    `## ${H.questions[l]}`, bullets(t.questions, l), '',
  ].join('\n')
}

// Befüllter Vorschlag für das jeweilige Formular; `org`: Organisationsdaten (nur für die Platzhalter). → Objekt oder null
function build(kind, id, lang, org) {
  if (!KINDS.includes(kind) || !DATA[kind][id]) return null
  const t = DATA[kind][id]
  const l = pickLang(lang)
  if (kind === 'bia') return {
    title: t.title[l], processOwner: '', department: t.department[l], criticality: t.criticality, rto: t.rto, rpo: t.rpo, mtpd: t.mtpd,
    dependencies: split(t.dependencies[l]), affectedSystems: split(t.systems[l]), status: 'draft', notes: t.notes[l], unresolved: [],
  }
  if (kind === 'plan') {
    const filled = safeDraft.fillPlaceholders(planText(t, l), org || {})
    return { title: t.title[l], type: t.type, scope: t.scope[l], status: 'draft', version: '1.0', procedures: filled.text, unresolved: filled.unresolved }
  }
  const filled = safeDraft.fillPlaceholders(exerciseText(t, l), org || {})
  return { title: t.title[l], type: t.type, result: 'planned', scenario: filled.text, findings: '', actions: '', unresolved: filled.unresolved }
}

module.exports = { LANGUAGES, KINDS, DATA, list, build }
